    /**
     * 주문을 완료 상태로 변경하고 관련된 후속 작업을 처리합니다.
     *
     * @param orderId 완료할 주문 ID
     */
    @Transactional
    public void completeOrder(Long orderId) {
        log.info("주문 완료 처리 시작: orderId={}", orderId);

        try {
            // OrderBid 조회
            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
